action.mutation:
mutation CreateQualityInterval($payload: [QualityIntervalCreatePayloadInput!]!) {
  mutation: createQualityInterval(payload: $payload) { 
    id
    name
  }
}

mutation UpdateQualityInterval($payload: [QualityIntervalUpdatePayloadInput!]!) {
  mutation: updateQualityInterval(payload: $payload) { 
    id
    name
  }
}

mutation DeleteQualityInterval($payload: [QualityIntervalDeletePayloadInput!]!) {
  mutation: deleteQualityInterval(payload: $payload) { 
    id
    name
  }
}
